join public.card_definitions d on d.code = k.code
on conflict (definition_id) do nothing;

do $$
begin
  if (select count(*) from public.card_definitions d join public.combat_kits k on k.definition_id = d.id
      where d.code in ('P110', 'P117', 'P032', 'P034', 'P035', 'P088', 'P027', 'P069', 'P070', 'P126', 'P169', 'P029', 'P072', 'P098', 'P160', 'P164', 'P165', 'P198', 'P038', 'P085', 'P086', 'P099', 'P109', 'P167', 'P201')) <> 25 then
    raise exception 'a character of the fourth batch has no kit';
  end if;
end $$;
